import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static String next() {
        while (buf[pos] <= ' ') pos++;
        int start = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, start, pos - start);
    }

    static long nextLong() {
        while (buf[pos] <= ' ') pos++;
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > ' ') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = nextInt();
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = nextLong();
        Arrays.sort(a);
        long answer = Math.max(1, a[n - 1] - a[0]);
        // split the sorted holes into a[0..i-1] and a[i..n-1], one board each
        for (int i = 1; i < n; i++)
            answer = Math.min(answer, Math.max(1, Math.max(a[i - 1] - a[0], a[n - 1] - a[i])));
        System.out.println(answer);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"sort"
	"strconv"
)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<20)
	sc.Split(bufio.ScanWords)
	next := func() int {
		sc.Scan()
		v, _ := strconv.Atoi(sc.Text())
		return v
	}
	n := next()
	a := make([]int, n)
	for i := range a {
		a[i] = next()
	}
	sort.Ints(a)
	answer := max(1, a[n-1]-a[0])
	// split the sorted holes into a[0..i-1] and a[i..n-1], one board each
	for i := 1; i < n; i++ {
		answer = min(answer, max(1, a[i-1]-a[0], a[n-1]-a[i]))
	}
	fmt.Println(answer)
}
